name: "invoice.pdf",
url: "https://cdn.example.com/docs/invoice.pdf",
},
],
schema: {
fields: [
{
type: "TEXT",
name: "invoice_number",
description: "The invoice or document number",
},
{
type: "CURRENCY_AMOUNT",
name: "total_amount",
description: "The total amount due",
},
